<?php

declare(strict_types=1);

namespace App\Payouts\Rails;

use App\Models\Payout;
use App\Payouts\Contracts\PayoutRail;
use App\Payouts\PayoutResult;

/**
 * Records a payout as paid OFFLINE — the operator has made the bank transfer outside the system and
 * is confirming it here (Phase 3 · Module 1 Step 5). The only working rail. No external reference is
 * generated by the system; the operator may attach one via `notes`/`external_ref`.
 */
class ManualPayoutRail implements PayoutRail
{
    public function name(): string
    {
        return 'manual';
    }

    public function send(Payout $payout): PayoutResult
    {
        return new PayoutResult(successful: true);
    }
}
